question.solution:
def longest_consecutive(nums):
    numbers = set(nums)
    best = 0
    for value in numbers:
        if value - 1 in numbers:
            continue
        length = 1
        while value + length in numbers:
            length += 1
        if length > best:
            best = length
    return best

print(longest_consecutive([100, 4, 200, 1, 3, 2]))
print(longest_consecutive([]))
print(longest_consecutive([1, 1, 2, 2, 3]))
